impl Default for Options {
	fn default() -> Self {
		Self {
			collection: constants::collection::TOP_FREE,
			category: constants::category::APPLICATION,
			age: None,
			num: 500,
			lang: String::from("en"),
			country: String::from("us"),
			full_detail: None,
		}
	}
}
