	async fn fetch_valid_top_free_apps() {
		let opts = Options {
			collection: collection::TOP_FREE,
			num: 100,
			..Options::default()
		};
		let req = Request::try_from(&opts).expect("Failed to create request");
		let client = cc();
		let res = client
			.execute(req)
			.await
			.expect("Failed to execute request");
		let res = opts
			.parse_response(res)
			.await
			.expect("Failed to parse response");
		for app in res {
			app.assert_valid();
			assert!(app.free);
		}
	}

